import { useEffect, useRef, useState, type FormEvent } from 'react'

import { useLang } from '../lib/i18n'
import { gsap, prefersReduced, rng } from '../lib/gsap'
import { submitInquiry } from '../lib/submit'
import { site } from '../content/site'
import { ui } from '../content/ui'
import { Arrow } from '../components/Brand'

type Status = 'idle' | 'sending' | 'done' | 'error'

type FieldProps = {
  id: string
  label: string
  type?: string
  required?: boolean
  error?: string
  textarea?: boolean
  autoComplete?: string
  onEdit?: () => void
}

// Intentionally independent of the global dark-theme .field style.
// This section switches the site to a lighter, more editorial palette.
function Field({
  id,
  label,
  type = 'text',
  required,
  error,
  textarea,
  autoComplete,
  onEdit,
}: FieldProps) {
  const { tr } = useLang()

  const common = {
    id,
    name: id,
    required,
    onInput: onEdit,
    'aria-invalid': error ? (true as const) : undefined,
    'aria-describedby': error ? `${id}-err` : undefined,
    placeholder: ' ',
    dir: 'auto' as const,
  }

  const inputClass = [
    'block w-full rounded-[15px] border bg-[#FFFEFB] px-4 py-[15px]',
    'text-[15px] leading-relaxed text-[#23201D] outline-none',
    'transition-[border-color,box-shadow,background-color] duration-300',
    'focus:border-[#F6620D] focus:ring-4 focus:ring-[#F6620D]/10',
    'placeholder:text-[#B1A99F]',
    error ? 'border-red-500' : 'border-[#DED7CD] hover:border-[#BCB1A4]',
  ].join(' ')

  return (
    <div className="min-w-0">
      <label
        htmlFor={id}
        className="mb-2.5 block text-[11px] font-bold uppercase tracking-[0.13em] text-[#544E47]"
      >
        {label}
        {required && (
          <>
            <span className="sr-only"> ({tr(ui.contact.required)})</span>
            <span className="ms-1 text-[#F6620D]" aria-hidden="true">*</span>
          </>
        )}
      </label>

      {textarea ? (
        <textarea
          {...common}
          rows={4}
          className={`${inputClass} min-h-[132px] resize-y`}
        />
      ) : (
        <input
          {...common}
          type={type}
          autoComplete={autoComplete}
          className={inputClass}
        />
      )}

      {error && (
        <p id={`${id}-err`} className="mt-2 text-xs text-red-600" role="alert">
          {error}
        </p>
      )}
    </div>
  )
}

export function Contact({ heading = 'h2' }: { heading?: 'h1' | 'h2' }) {
  const { tr, lang } = useLang()
  const [cats, setCats] = useState<string[]>([])
  const [errors, setErrors] = useState<{ name?: string; email?: string }>({})
  const [status, setStatus] = useState<Status>('idle')

  const sectionRef = useRef<HTMLElement>(null)
  const visualRef = useRef<HTMLDivElement>(null)
  const imageRef = useRef<HTMLDivElement>(null)
  const formBox = useRef<HTMLDivElement>(null)
  const fx = useRef<HTMLDivElement>(null)

  const Heading = heading
  const wa = site.whatsapp ? `https://wa.me/${site.whatsapp}` : undefined
  const isArabic = lang === 'ar'

  // Reveal only as elements enter the viewport; default HTML remains visible
  // for users with reduced motion and browsers without IntersectionObserver.
  useEffect(() => {
    const section = sectionRef.current
    if (!section || prefersReduced() || !('IntersectionObserver' in window)) return

    const targets = Array.from(
      section.querySelectorAll<HTMLElement>('[data-contact-reveal]'),
    )
    gsap.set(targets, { autoAlpha: 0, y: 26 })

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (!entry.isIntersecting) return
          observer.unobserve(entry.target)
          gsap.to(entry.target, {
            autoAlpha: 1,
            y: 0,
            duration: 0.95,
            ease: 'power3.out',
            overwrite: 'auto',
          })
        })
      },
      { threshold: 0.07, rootMargin: '0px 0px -25px 0px' },
    )

    targets.forEach((target) => observer.observe(target))
    return () => {
      observer.disconnect()
      gsap.killTweensOf(targets)
      gsap.set(targets, { clearProps: 'all' })
    }
  }, [])

  // A restrained photo-parallax effect, mouse only. No layout thrashing.
  useEffect(() => {
    const panel = visualRef.current
    const image = imageRef.current
    if (!panel || !image || prefersReduced()) return

    const moveX = gsap.quickTo(image, 'x', { duration: 0.9, ease: 'power3.out' })
    const moveY = gsap.quickTo(image, 'y', { duration: 0.9, ease: 'power3.out' })

    const move = (event: PointerEvent) => {
      if (event.pointerType !== 'mouse') return
      const rect = panel.getBoundingClientRect()
      moveX(((event.clientX - rect.left) / rect.width - 0.5) * 18)
      moveY(((event.clientY - rect.top) / rect.height - 0.5) * 18)
    }
    const leave = () => {
      moveX(0)
      moveY(0)
    }
    panel.addEventListener('pointermove', move)
    panel.addEventListener('pointerleave', leave)
    return () => {
      panel.removeEventListener('pointermove', move)
      panel.removeEventListener('pointerleave', leave)
      gsap.killTweensOf(image)
      gsap.set(image, { clearProps: 'x,y' })
    }
  }, [])

  const toggle = (category: string, element: HTMLButtonElement) => {
    setCats((current) =>
      current.includes(category)
        ? current.filter((item) => item !== category)
        : [...current, category],
    )
    if (!prefersReduced()) {
      gsap.fromTo(
        element,
        { scale: 0.94 },
        { scale: 1, duration: 0.4, ease: 'back.out(2)' },
      )
    }
  }

  // Brand-orange particles converge after the submission succeeds.
  // The real API request is never interrupted by the visual animation.
  const celebrate = () =>
    new Promise<void>((resolve) => {
      const layer = fx.current
      const box = formBox.current
      if (!layer || !box || prefersReduced()) return resolve()

      const { width, height } = box.getBoundingClientRect()
      const random = rng(Date.now() & 0xffff)
      const targetX = width * 0.5
      const targetY = height * 0.48
      const particles = Array.from({ length: 24 }, () => {
        const particle = document.createElement('span')
        const diameter = 3 + random() * 5
        particle.className = 'absolute block rounded-full'
        particle.style.width = `${diameter}px`
        particle.style.height = `${diameter}px`
        particle.style.background = random() > 0.35 ? '#F6620D' : '#D8B991'
        layer.appendChild(particle)
        gsap.set(particle, {
          x: random() * width,
          y: random() * height,
          opacity: 0,
          scale: 0.5,
        })
        return particle
      })

      const timeline = gsap.timeline({
        onComplete: () => {
          particles.forEach((particle) => particle.remove())
          resolve()
        },
      })
      timeline.to(particles, {
        opacity: 0.9,
        duration: 0.22,
        stagger: { each: 0.012, from: 'random' },
      })
      timeline.to(
        particles,
        {
          x: targetX,
          y: targetY,
          scale: 0,
          opacity: 0,
          duration: 0.55,
          ease: 'power3.in',
          stagger: { each: 0.008, from: 'random' },
        },
        '-=0.05',
      )
    })

  const onSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (status === 'sending') return

    const data = new FormData(event.currentTarget)
    const value = (key: string) => String(data.get(key) ?? '').trim()
    const nextErrors: typeof errors = {}

    if (!value('name')) nextErrors.name = tr(ui.contact.errName)
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value('email'))) {
      nextErrors.email = tr(ui.contact.errEmail)
    }
    setErrors(nextErrors)

    if (nextErrors.name || nextErrors.email) {
      const invalid = nextErrors.name ? 'name' : 'email'
      ;(event.currentTarget.elements.namedItem(invalid) as HTMLElement | null)?.focus()
      return
    }

    setStatus('sending')
    try {
      await submitInquiry({
        name: value('name'),
        company: value('company'),
        email: value('email'),
        phone: value('phone'),
        message: value('message'),
        categories: cats,
        lang,
      })
      await celebrate()
      setStatus('done')
    } catch {
      setStatus('error')
    }
  }

  const reset = () => {
    setCats([])
    setErrors({})
    setStatus('idle')
  }

  return (
    <section
      id="contact"
      ref={sectionRef}
      dir={isArabic ? 'rtl' : 'ltr'}
      aria-label={tr(ui.contact.eyebrow)}
      className="relative isolate scroll-mt-20 overflow-hidden bg-[#F0EDE7] py-16 text-[#221E1B] sm:py-20 lg:py-28"
    >
      {/* Cream paper, subtle warmth, not another all-blue section. */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-0"
        style={{
          background:
            'radial-gradient(ellipse at 7% 8%, rgba(246,98,13,.075), transparent 30%), radial-gradient(ellipse at 100% 100%, rgba(104,75,48,.08), transparent 38%)',
        }}
      />
      <span
        aria-hidden="true"
        className="pointer-events-none absolute -end-[14rem] -top-[12rem] hidden h-[28rem] w-[28rem] rounded-full border border-[#CFC4B6]/60 xl:block"
      />

      <div className="wrap relative">
        {/* Slim editorial section index */}
        <div
          className="mb-7 flex flex-wrap items-center justify-between gap-4 border-b border-[#29221B]/15 pb-5 sm:mb-9"
          data-contact-reveal
        >
          <div className="flex items-center gap-3">
            <span className="h-2.5 w-2.5 rounded-full bg-[#F6620D] shadow-[0_0_0_6px_rgba(246,98,13,.10)]" />
            <span className="text-[11px] font-bold uppercase tracking-[0.28em] text-[#40372D]">
              {tr(ui.contact.eyebrow)}
            </span>
          </div>
          <span className="text-[10px] font-semibold uppercase tracking-[0.22em] text-[#81776C]">
            {tr({ en: 'An invitation to make something great', ar: 'دعوة لصناعة شيء استثنائي' })}
          </span>
        </div>

        <div className="grid items-stretch gap-5 lg:grid-cols-[minmax(0,0.94fr)_minmax(0,1.06fr)] lg:gap-6">
          {/* The visual is a genuine background image, separate from the UI. */}
          <div
            ref={visualRef}
            className="group relative isolate flex min-h-[660px] flex-col overflow-hidden rounded-[26px] bg-[#171717] text-white shadow-[0_20px_60px_rgba(35,25,16,.16)] sm:min-h-[740px] sm:rounded-[34px] lg:min-h-[800px]"
            data-contact-reveal
          >
            <div ref={imageRef} className="pointer-events-none absolute -inset-[2.5%]">
              <img
                src="/images/contact/creative-mind-contact.webp"
                alt=""
                aria-hidden="true"
                loading="lazy"
                decoding="async"
                width={941}
                height={1672}
                className="h-full w-full object-cover object-[50%_40%]"
              />
            </div>

            <div
              className="pointer-events-none absolute inset-0"
              aria-hidden="true"
              style={{
                background:
                  'linear-gradient(180deg, rgba(17,16,15,.94) 0%, rgba(17,16,15,.77) 22%, rgba(17,16,15,.10) 49%, rgba(17,16,15,.13) 67%, rgba(17,16,15,.93) 100%)',
              }}
            />

            <div className="relative z-10 p-7 sm:p-10 lg:p-11">
              <div className="mb-7 flex items-center gap-3 text-[10px] font-semibold uppercase tracking-[0.26em] text-white/65 sm:mb-9">
                <span className="h-px w-8 bg-[#FF7831]" />
                {tr({ en: 'The next chapter starts here', ar: 'الفصل القادم يبدأ من هنا' })}
              </div>

              <Heading className="max-w-[11ch] text-[clamp(2.75rem,5vw,5.25rem)] font-semibold leading-[1.02] tracking-[-0.055em] text-[#FFF9F3] rtl:max-w-none rtl:leading-[1.22] rtl:tracking-normal">
                <span className="block font-light">{ui.contact.title[lang][0]}</span>
                <span className="block text-[#FF7A30]">{ui.contact.title[lang][1]}</span>
              </Heading>

              <p className="mt-6 max-w-[34ch] text-sm leading-[1.8] text-white/75 sm:text-[15px]">
                {tr(ui.contact.intro)}
              </p>
            </div>

            <div className="relative z-10 mt-auto p-7 pt-32 sm:p-10 sm:pt-36 lg:p-11 lg:pt-40">
              <div className="mb-5 flex items-center gap-3">
                <span className="h-px w-9 bg-[#FF7831]" />
                <span className="text-[10px] font-semibold uppercase tracking-[0.25em] text-white/60">
                  {tr({ en: 'Prefer to talk directly?', ar: 'تفضّل التواصل المباشر؟' })}
                </span>
              </div>
              <div className="flex flex-wrap items-center gap-3">
                {wa && (
                  <a
                    href={wa}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="inline-flex min-h-12 items-center gap-3 rounded-full border border-white/30 bg-white/10 px-5 text-sm font-semibold text-white backdrop-blur-md transition-all duration-300 hover:-translate-y-0.5 hover:border-[#FF7A30] hover:bg-[#F6620D] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[#FF7A30]"
                  >
                    {tr(ui.contact.whatsapp)} <span aria-hidden="true">↗</span>
                  </a>
                )}
                <a
                  href={`mailto:${site.email}`}
                  className="inline-flex min-h-12 min-w-0 items-center gap-2 rounded-full border border-white/20 px-5 text-sm text-white/90 transition-colors duration-300 hover:border-white/65 hover:text-white focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[#FF7A30]"
                >
                  <span className="truncate">{site.email}</span>
                  <span aria-hidden="true">↗</span>
                </a>
              </div>
            </div>

            <span
              aria-hidden="true"
              className="pointer-events-none absolute end-5 top-5 z-10 hidden select-none text-[10px] font-semibold tracking-[.22em] text-white/30 sm:block [writing-mode:vertical-rl]"
            >
              CREATIVE MIND / STUDIO
            </span>
          </div>

          {/* Warm paper form. All previous field names / payload keys stay intact. */}
          <div
            ref={formBox}
            className="relative isolate overflow-hidden rounded-[26px] border border-[#E5DED4] bg-[#FCFAF6] shadow-[0_20px_60px_rgba(35,25,16,.07)] sm:rounded-[34px]"
            data-contact-reveal
          >
            <div ref={fx} className="pointer-events-none absolute inset-0 z-20" aria-hidden="true" />
            <span
              aria-hidden="true"
              className="pointer-events-none absolute end-[-90px] top-[-94px] h-[230px] w-[230px] rounded-full border border-[#E9E0D5]"
            />
            <span
              aria-hidden="true"
              className="pointer-events-none absolute end-[-45px] top-[-47px] h-[150px] w-[150px] rounded-full border border-[#E9E0D5]"
            />

            {status === 'done' ? (
              <div className="relative z-10 flex min-h-[660px] flex-col items-start justify-center p-8 sm:p-12 lg:p-14" role="status">
                <span className="mb-9 inline-flex h-20 w-20 items-center justify-center rounded-[24px] bg-[#F6620D] text-4xl text-white shadow-[0_18px_50px_rgba(246,98,13,.25)]" aria-hidden="true">✓</span>
                <p className="mb-4 text-[11px] font-bold uppercase tracking-[.24em] text-[#B15B2F]">
                  {tr({ en: 'Message received', ar: 'تم استلام رسالتك' })}
                </p>
                <h3 className="max-w-[14ch] text-[clamp(2.5rem,4vw,4.25rem)] font-semibold leading-[1.08] tracking-[-.045em] text-[#231E1A] rtl:max-w-none rtl:leading-snug rtl:tracking-normal">
                  {tr(ui.contact.success)}
                  <span className="block font-light text-[#B15B2F]">{tr(ui.contact.success2)}</span>
                </h3>
                <button
                  type="button"
                  onClick={reset}
                  className="mt-10 inline-flex items-center gap-3 border-b border-[#1F1A16] pb-2 text-sm font-semibold text-[#241E19] transition-colors hover:border-[#F6620D] hover:text-[#F6620D] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[#F6620D]"
                >
                  {tr(ui.contact.again)} <span aria-hidden="true">↗</span>
                </button>
              </div>
            ) : (
              <form
                onSubmit={onSubmit}
                noValidate
                aria-busy={status === 'sending'}
                className="relative z-10 flex h-full flex-col px-7 py-9 sm:px-10 sm:py-11 lg:px-[clamp(2rem,3.3vw,3.5rem)] lg:py-[clamp(2.4rem,3.3vw,3.5rem)]"
              >
                <div className="mb-9 flex items-center justify-between gap-3">
                  <span className="text-[11px] font-bold uppercase tracking-[.23em] text-[#AD582D]">
                    {tr({ en: 'Your project / The brief', ar: 'مشروعك / التفاصيل' })}
                  </span>
                  <span className="flex h-10 w-10 items-center justify-center rounded-full border border-[#DCD1C3] text-lg text-[#F6620D]" aria-hidden="true">✳</span>
                </div>

                <h3 className="max-w-[13ch] text-[clamp(2.35rem,3.5vw,3.8rem)] font-semibold leading-[1.08] tracking-[-.045em] text-[#211C18] rtl:max-w-none rtl:leading-snug rtl:tracking-normal">
                  {tr({ en: 'Tell us what you imagine.', ar: 'أخبرنا عمّا تتخيّله.' })}
                </h3>
                <p className="mt-4 mb-10 max-w-[43ch] text-sm leading-relaxed text-[#7A7167]">
                  {tr({
                    en: 'No complicated brief needed. Just share what you have in mind, and let’s begin the conversation.',
                    ar: 'لا تحتاج إلى تقديم تفاصيل معقّدة. شاركنا فكرتك، ولنبدأ الحديث عنها.',
                  })}
                </p>

                <div className="grid gap-x-5 gap-y-6 sm:grid-cols-2">
                  <Field
                    id="name"
                    label={tr(ui.contact.name)}
                    required
                    error={errors.name}
                    autoComplete="name"
                    onEdit={() => errors.name && setErrors((current) => ({ ...current, name: undefined }))}
                  />
                  <Field
                    id="company"
                    label={tr(ui.contact.company)}
                    autoComplete="organization"
                  />
                  <Field
                    id="email"
                    label={tr(ui.contact.email)}
                    type="email"
                    required
                    error={errors.email}
                    autoComplete="email"
                    onEdit={() => errors.email && setErrors((current) => ({ ...current, email: undefined }))}
                  />
                  <Field
                    id="phone"
                    label={tr(ui.contact.phone)}
                    type="tel"
                    autoComplete="tel"
                  />
                </div>

                <fieldset className="mt-9">
                  <legend className="mb-4 text-[11px] font-bold uppercase tracking-[.13em] text-[#544E47]">
                    {tr(ui.contact.need)}
                  </legend>
                  <div className="flex flex-wrap gap-2">
                    {ui.contact.cats.map((category) => {
                      const selected = cats.includes(category.en)
                      return (
                        <button
                          key={category.en}
                          type="button"
                          aria-pressed={selected}
                          disabled={status === 'sending'}
                          onClick={(event) => toggle(category.en, event.currentTarget)}
                          className={`rounded-full border px-3.5 py-2.5 text-xs font-medium transition-all duration-300 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#F6620D] disabled:opacity-60 ${
                            selected
                              ? 'border-[#F6620D] bg-[#F6620D] text-white shadow-[0_4px_15px_rgba(246,98,13,.20)]'
                              : 'border-[#DAD2C8] bg-white/70 text-[#655A50] hover:border-[#F6620D] hover:bg-[#FFF3EA] hover:text-[#AE4611]'
                          }`}
                        >
                          {selected && <span className="me-1" aria-hidden="true">✓</span>}
                          {tr(category)}
                        </button>
                      )
                    })}
                  </div>
                </fieldset>

                <div className="mt-8">
                  <Field id="message" label={tr(ui.contact.message)} textarea />
                </div>

                {status === 'error' && (
                  <p role="alert" className="mt-5 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">
                    {tr(ui.contact.errSend)}
                  </p>
                )}

                <div className="mt-auto pt-9">
                  <button
                    type="submit"
                    disabled={status === 'sending'}
                    className="group flex min-h-[62px] w-full items-center justify-between gap-4 rounded-[18px] bg-[#F6620D] ps-6 pe-3 text-start text-[13px] font-bold uppercase tracking-[.075em] text-white shadow-[0_14px_30px_rgba(246,98,13,.22)] transition-all duration-300 hover:-translate-y-0.5 hover:bg-[#D94F03] hover:shadow-[0_18px_38px_rgba(246,98,13,.29)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[#F6620D] disabled:cursor-wait disabled:opacity-70 disabled:hover:translate-y-0"
                  >
                    <span>{tr(status === 'sending' ? ui.contact.sending : ui.cta)}</span>
                    <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-[12px] bg-white/15 transition-transform duration-300 group-hover:-rotate-45 rtl:group-hover:rotate-45" aria-hidden="true">
                      {status === 'sending'
                        ? <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white" />
                        : <Arrow className="h-5 w-5 rtl:-scale-x-100" />}
                    </span>
                  </button>
                  <p className="mt-4 flex items-center justify-center gap-2 text-center text-[11px] leading-relaxed text-[#92877A]">
                    <span className="h-1.5 w-1.5 shrink-0 rounded-full bg-[#F6620D]" aria-hidden="true" />
                    {tr({
                      en: 'We’ll use your details to respond to your inquiry.',
                      ar: 'سنستخدم بياناتك للردّ على استفسارك.',
                    })}
                  </p>
                </div>
              </form>
            )}
          </div>
        </div>

        <div
          className="mt-8 flex flex-wrap items-center justify-between gap-4 border-t border-[#29221B]/15 pt-5 text-[10px] font-semibold uppercase tracking-[.20em] text-[#756A5F]"
          data-contact-reveal
        >
          <span>{tr({ en: 'From a first hello to the next big thing.', ar: 'من أول تحية إلى إنجاز استثنائي.' })}</span>
          <span className="inline-flex items-center gap-2">
            <span className="h-[6px] w-[6px] rounded-full bg-[#F6620D]" />
            CREATIVE MIND
          </span>
        </div>
      </div>
    </section>
  )
}
